package com.eventpulse.service;
import com.eventpulse.exception.*; import com.eventpulse.model.*; import com.eventpulse.repository.*; import java.time.*; import java.util.*;
public class RegistrationService {
 private final RegistrationRepository registrations; private final EventService events; private final Clock clock;
 public RegistrationService(RegistrationRepository r,EventService e){this(r,e,Clock.systemUTC());} public RegistrationService(RegistrationRepository r,EventService e,Clock c){registrations=r;events=e;clock=c;}
 public Registration register(String eventId,String userId){Event e=events.get(eventId);Instant now=clock.instant();String status=e.getStatus();if("CANCELLED".equals(status))throw new RegistrationException("Cannot register for a cancelled event.");if("COMPLETED".equals(status))throw new RegistrationException("Registration is closed because this event has completed.");Instant start;try{start=Instant.parse(e.getStartDateTime());}catch(RuntimeException invalidStart){throw new RegistrationException("Registration is only available for upcoming events.");}if("ONGOING".equals(status)||!start.isAfter(now))throw new RegistrationException("Registration is closed because this event has already started.");if(!"UPCOMING".equals(status))throw new RegistrationException("Registration is only available for upcoming events.");if(registrations.findUserEvent(userId,eventId).filter(r->"ACTIVE".equals(r.getStatus())).isPresent())throw new RegistrationException("User is already registered for this event"); Registration r=new Registration();r.setRegistrationId(UUID.nameUUIDFromBytes((userId+":"+eventId).getBytes()).toString());r.setEventId(eventId);r.setUserId(userId);r.setStatus("ACTIVE");r.setRegisteredAt(Instant.now(clock).toString());try{return registrations.create(r);}catch(software.amazon.awssdk.services.dynamodb.model.ConditionalCheckFailedException ex){throw new RegistrationException("User already has a registration record for this event");}}
 public List<Registration> forUser(String id){return registrations.forUser(id);} public List<Registration> forEvent(String id){return registrations.forEvent(id);}
 public Registration cancel(String id,String requester){Registration r=registrations.findById(id).orElseThrow(()->new RegistrationException("Registration not found"));if(!r.getUserId().equals(requester))throw new RegistrationException("Registration not found"); if(!"CANCELLED".equals(r.getStatus())){r.setStatus("CANCELLED");r.setCancelledAt(Instant.now(clock).toString());return registrations.save(r);}return r;}
}
